// ThePillory: shared behavior for the app screens.
// - Global search (dropdown on every tab, full results on /search/)
// - Tabs on rep profiles (#overview, #promises, #votes, #issues)
// - The first-visit intro on Home (dismissed once, remembered in this browser)
// - Links to an agenda item open its collapsed section on meeting pages
// The search data comes from assets/search-index.js (governing bodies and the
// Constitution, generated by tools/build.py) and /api/search-officials (D1).

(function () {
  "use strict";

  var INDEX = window.PILLORY_INDEX || [];
  var DROPDOWN_LIMIT = 8;

  function norm(s) {
    return String(s || "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
  }

  function search(query) {
    var tokens = norm(query).split(/\s+/).filter(Boolean);
    if (!tokens.length) return [];
    return INDEX.filter(function (item) {
      var hay = norm([item.type, item.title, item.sub, item.k].join(" "));
      return tokens.every(function (t) { return hay.indexOf(t) !== -1; });
    });
  }

  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  }

  function resultLink(item) {
    var a = el("a", "search-result");
    a.href = item.url;
    a.appendChild(el("span", "search-result-type", item.type));
    a.appendChild(el("span", "search-result-title", item.title));
    if (item.sub) a.appendChild(el("span", "search-result-sub", item.sub));
    return a;
  }

  function searchUrl(q) {
    return "/search/?q=" + encodeURIComponent(q);
  }

  // Dropdown results under every search bar.
  document.querySelectorAll("form.search").forEach(function (form) {
    var input = form.querySelector("input");
    var box = form.querySelector(".search-results");

    function close() {
      box.hidden = true;
      input.setAttribute("aria-expanded", "false");
    }

    function render() {
      var q = input.value.trim();
      box.textContent = "";
      if (!q || document.getElementById("search-page-results")) return close();
      var results = search(q);
      results.slice(0, DROPDOWN_LIMIT).forEach(function (item) { box.appendChild(resultLink(item)); });
      if (!results.length) box.appendChild(el("p", "search-empty", "No matches."));
      if (results.length > DROPDOWN_LIMIT) {
        var all = el("a", "search-all", "See all " + results.length + " results");
        all.href = searchUrl(q);
        box.appendChild(all);
      }
      box.hidden = false;
      input.setAttribute("aria-expanded", "true");
    }

    input.addEventListener("input", render);
    input.addEventListener("focus", render);
    form.addEventListener("keydown", function (e) {
      var links = Array.prototype.slice.call(box.querySelectorAll("a"));
      var i = links.indexOf(document.activeElement);
      if (e.key === "Escape") {
        close();
        input.focus();
      } else if (e.key === "ArrowDown" && links.length) {
        e.preventDefault();
        links[Math.min(i + 1, links.length - 1)].focus();
      } else if (e.key === "ArrowUp" && i !== -1) {
        e.preventDefault();
        (i === 0 ? input : links[i - 1]).focus();
      }
    });
    document.addEventListener("click", function (e) {
      if (!form.contains(e.target)) close();
    });
  });

  // Full results page: /search/?q=...
  var page = document.getElementById("search-page-results");
  if (page) {
    var input = document.querySelector("form.search input");
    var renderPage = function () {
      var q = input ? input.value.trim() : "";
      page.textContent = "";
      if (!q) {
        page.appendChild(el("p", "secondary", "Type to search reps, governing bodies, bills, meetings, and the Constitution."));
        return;
      }
      var results = search(q);
      if (!results.length) {
        page.appendChild(el("p", "secondary", "No matches for “" + q + "”."));
        return;
      }
      var groups = {};
      var order = [];
      results.forEach(function (item) {
        if (!groups[item.type]) { groups[item.type] = []; order.push(item.type); }
        groups[item.type].push(item);
      });
      order.forEach(function (type) {
        var section = el("section", "card stack-sm");
        section.appendChild(el("h2", "label", type));
        groups[type].forEach(function (item) { section.appendChild(resultLink(item)); });
        page.appendChild(section);
      });
    };
    if (input) {
      input.value = new URLSearchParams(location.search).get("q") || "";
      input.addEventListener("input", function () {
        history.replaceState(null, "", input.value.trim() ? searchUrl(input.value.trim()) : "/search/");
        renderPage();
      });
    }
    renderPage();
  }

  // First-visit intro (Home). Hidden in the HTML; shown unless dismissed before.
  var INTRO_KEY = "pillory-intro-dismissed";
  var intro = document.querySelector("[data-intro]");
  if (intro) {
    var dismissed = false;
    try { dismissed = localStorage.getItem(INTRO_KEY) === "1"; } catch (_) {}
    if (!dismissed) intro.hidden = false;
    var close = intro.querySelector("[data-intro-dismiss]");
    if (close) close.addEventListener("click", function () {
      intro.hidden = true;
      try { localStorage.setItem(INTRO_KEY, "1"); } catch (_) {}
    });
  }

  // A link to an agenda item (#item-…) opens the collapsed section it's in.
  function openTarget() {
    var id = location.hash.slice(1);
    var target = id && document.getElementById(id);
    var box = target && target.closest ? target.closest("details") : null;
    if (box && !box.open) {
      box.open = true;
      target.scrollIntoView();
    }
  }
  window.addEventListener("hashchange", openTarget);
  openTarget();

  // Tabs (rep profile). Without JS every panel shows and the tab links jump to them.
  document.querySelectorAll("[data-tabs]").forEach(function (root) {
    var tabs = Array.prototype.slice.call(root.querySelectorAll('[role="tab"]'));
    var ids = tabs.map(function (t) { return t.getAttribute("aria-controls"); });

    function show(id, focus) {
      tabs.forEach(function (t) {
        var on = t.getAttribute("aria-controls") === id;
        t.setAttribute("aria-selected", on ? "true" : "false");
        t.tabIndex = on ? 0 : -1;
        document.getElementById(t.getAttribute("aria-controls")).hidden = !on;
        if (on && focus) t.focus();
      });
    }

    tabs.forEach(function (t, i) {
      t.addEventListener("click", function (e) {
        e.preventDefault();
        var id = t.getAttribute("aria-controls");
        history.replaceState(null, "", "#" + id);
        show(id);
      });
      t.addEventListener("keydown", function (e) {
        var next = e.key === "ArrowRight" ? i + 1 : e.key === "ArrowLeft" ? i - 1 : null;
        if (next === null) return;
        e.preventDefault();
        show(ids[(next + ids.length) % ids.length], true);
      });
    });

    // A tab's own id opens it; the id of something inside a panel (#disclosures,
    // #orders) opens that panel and scrolls to it. Old links: #overview is About.
    var ALIASES = { overview: "about" };
    function fromHash() {
      var id = ALIASES[location.hash.slice(1)] || location.hash.slice(1);
      if (ids.indexOf(id) !== -1) return show(id);
      var target = id && document.getElementById(id);
      var panel = target && target.closest ? target.closest('[role="tabpanel"]') : null;
      if (panel && root.contains(panel)) {
        show(panel.id);
        target.scrollIntoView();
        return;
      }
      show(ids[0]);
    }
    window.addEventListener("hashchange", fromHash);
    fromHash();
  });
  // ---------------------------------------------------------------------
  // Find your representatives. The address or ZIP goes to /api/districts,
  // which answers with district IDs only; this browser keeps those IDs in
  // the pillory_districts cookie (never the address). Without JS the form
  // posts to the same place and the server sets the cookie.
  var COOKIE = "pillory_districts";

  function saveDistricts(d) {
    var parts = [];
    Object.keys(d).forEach(function (k) { parts.push(k + "=" + encodeURIComponent(d[k])); });
    document.cookie = COOKIE + "=" + encodeURIComponent(parts.join("&")) + "; Path=/; Max-Age=31536000; SameSite=Lax" +
      (location.protocol === "https:" ? "; Secure" : "");
  }

  document.querySelectorAll("[data-forget-districts]").forEach(function (btn) {
    btn.addEventListener("click", function () {
      document.cookie = COOKIE + "=; Path=/; Max-Age=0; SameSite=Lax";
      location.href = "/";
    });
  });

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text) n.textContent = text;
    return n;
  }

  document.querySelectorAll("[data-district-lookup]").forEach(function (form) {
    var out = form.querySelector("[data-lookup-result]");
    var input = form.querySelector("input[name=q]");
    var button = form.querySelector("button[type=submit]");

    function show(nodes) {
      out.textContent = "";
      nodes.forEach(function (n) { out.appendChild(n); });
    }

    function done(d) {
      saveDistricts(d);
      show([el("p", "small", "Found your districts. Opening your briefing…")]);
      location.href = "/briefing/";
    }

    form.addEventListener("submit", function (e) {
      e.preventDefault();
      var q = (input.value || "").trim();
      if (!q) {
        show([el("p", "small form-error", "Enter a street address with city and state, or a ZIP code.")]);
        input.focus();
        return;
      }
      button.disabled = true;
      show([el("p", "small secondary", "Looking up your districts…")]);
      fetch("/api/districts", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ q: q }) })
        .then(function (r) { return r.json(); })
        .then(function (res) {
          button.disabled = false;
          if (res.found && res.districts) return done(res.districts);
          if (res.choices && res.choices.length) {
            var intro = el("p", "small", "This ZIP code is split between districts. Choose yours, or enter your street address instead.");
            var list = el("div", "choice-list");
            res.choices.forEach(function (c) {
              var b = el("button", "btn choice-btn", c.label);
              b.type = "button";
              b.addEventListener("click", function () { done(c.districts); });
              list.appendChild(b);
            });
            show([intro, list]);
            return;
          }
          show([el("p", "small form-error", res.error || "Something went wrong. Please try again.")]);
        })
        .catch(function () {
          button.disabled = false;
          show([el("p", "small form-error", "The lookup didn't answer. Check your connection and try again.")]);
        });
    });
  });

  // Waitlist: fill the county list for the chosen state (data/counties.json).
  document.querySelectorAll("[data-county-picker]").forEach(function (form) {
    var state = form.querySelector("select[name=state]");
    var county = form.querySelector("select[name=county]");
    var counties = null;
    function fill() {
      var st = state.value;
      county.textContent = "";
      county.appendChild(new Option(st ? "Choose a county" : "Choose a state first", ""));
      if (!st || !counties) return;
      Object.keys(counties)
        .filter(function (f) { return counties[f][1] === st; })
        .sort(function (a, b) { return counties[a][0].localeCompare(counties[b][0]); })
        .forEach(function (f) { county.appendChild(new Option(counties[f][0], f)); });
      county.disabled = false;
    }
    state.addEventListener("change", function () {
      if (counties) return fill();
      fetch("/data/counties.json").then(function (r) { return r.json(); }).then(function (c) { counties = c; fill(); });
    });
  });
  // ---------------------------------------------------------------------
  // "Load more" (the Laws list): the link opens the next page of that list,
  // which works without JavaScript; here, the next cards are appended in place
  // and the link moves on to the page after.
  document.addEventListener("click", function (e) {
    var link = e.target.closest ? e.target.closest("a[data-load-more]") : null;
    if (!link || e.metaKey || e.ctrlKey || e.shiftKey) return;
    var list = document.getElementById(link.getAttribute("data-load-more"));
    if (!list || !window.fetch || !window.DOMParser) return;
    e.preventDefault();
    if (link.getAttribute("aria-busy") === "true") return;
    link.setAttribute("aria-busy", "true");
    var label = link.textContent;
    link.textContent = "Loading…";
    fetch(link.href, { credentials: "same-origin" })
      .then(function (r) {
        if (!r.ok) throw new Error(r.status);
        return r.text();
      })
      .then(function (html) {
        var doc = new DOMParser().parseFromString(html, "text/html");
        var next = doc.getElementById(list.id);
        if (!next) throw new Error("no list");
        while (next.firstElementChild) list.appendChild(next.firstElementChild);
        var more = doc.querySelector('a[data-load-more="' + list.id + '"]');
        if (more) {
          link.href = more.getAttribute("href");
          link.textContent = label;
          link.removeAttribute("aria-busy");
        } else {
          link.remove();
        }
      })
      .catch(function () {
        // Fall back to opening the next page.
        window.location.href = link.href;
      });
  });
  // ---------------------------------------------------------------------
  // Cloudflare Turnstile, for the forms that have a .cf-turnstile widget (the
  // waitlist, "Something wrong?", "Request full analysis"). Its script is
  // loaded only after the page has finished loading: the challenge frame it
  // creates would otherwise hold up the load, and Safari shows a tab's icon
  // only once the page has loaded. The script renders every widget on the page
  // when it arrives.
  if (document.querySelector(".cf-turnstile")) {
    var loadTurnstile = function () {
      var s = document.createElement("script");
      s.src = "https://challenges.cloudflare.com/turnstile/v0/api.js";
      s.async = true;
      document.head.appendChild(s);
    };
    if (document.readyState === "complete") loadTurnstile();
    else window.addEventListener("load", loadTurnstile);
  }
})();
